definition.script:
def wealthDesc(String mod) {
  def mf = "${env.WORKSPACE}/.wealth-meta-${mod}"
  if (!fileExists(mf)) { return }
  def m = [:]
  for (l in readFile(mf).trim().split('\n')) {
    def i = l.indexOf('=')
    if (i > 0) { m[l.substring(0, i)] = l.substring(i + 1).trim() }
  }
  currentBuild.description = "分支 ${m.BRANCH} | SHA ${m.SHA} | tag ${m.IMAGE_TAG} | MODULE=${mod} MODE=${m.MODE} OVERLAY=${params.OVERLAY} BRANCH=${m.BRANCH} SHA=${m.SHA} IMAGE_TAG=${m.IMAGE_TAG}"
}

pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '10')) }
  stages {
    stage('Resolve source') {
      steps {
        sh '''
          set -euo pipefail
          export MODULE="auth"
          export MODE="${MODE}"
          export OVERLAY="${OVERLAY}"
          export SOURCE="${SOURCE}"
          export IMAGE_TAG="${IMAGE_TAG}"
          export REGISTRY="${REGISTRY:-}"
          export BRANCH="${BRANCH}"
          export GIT_SHA="${GIT_SHA:-}"
          export SKIP_MVN="$([ "${SKIP_MVN}" = "true" ] && echo 1 || echo 0)"
          export WORKSPACE_ROOT="${WORKSPACE}/repos"
          export JAVA_HOME=/opt/java/jdk-25
          export PATH="$JAVA_HOME/bin:/opt/maven/bin:/usr/local/bin:$PATH"
          export PREPARE_ONLY=1
          bash /jenkins-backup/scripts/pipeline-wealth-module.sh
        '''
        script { wealthDesc('auth') }
      }
    }
    stage('CI + CD') {
      steps {
        sh '''
          set -euo pipefail
          export MODULE="auth"
          export MODE="${MODE}"
          export OVERLAY="${OVERLAY}"
          export SOURCE="${SOURCE}"
          export IMAGE_TAG="${IMAGE_TAG}"
          export REGISTRY="${REGISTRY:-}"
          export BRANCH="${BRANCH}"
          export GIT_SHA="${GIT_SHA:-}"
          export SKIP_MVN="$([ "${SKIP_MVN}" = "true" ] && echo 1 || echo 0)"
          export WORKSPACE_ROOT="${WORKSPACE}/repos"
          export JAVA_HOME=/opt/java/jdk-25
          export PATH="$JAVA_HOME/bin:/opt/maven/bin:/usr/local/bin:$PATH"
          bash /jenkins-backup/scripts/pipeline-wealth-module.sh
        '''
      }
    }
  }
  post {
    always {
      script { wealthDesc('auth') }
    }
  }
}
